userscript.function:

	$sObject._vp.parents('body')[0].addEventListener('click', function(e){
		if(e.srcElement.classList.contains('frame')){
			window.top.Sepoa.callEvent('onMenuBlankClick', []);
		}
	})
    setTimeout(doQueryMenu,200);
    $(window).on({
        resize:function(){
            menuAreaResize();
        }
    });
    extendO2W($sObject);
    if(Sepoa.request.isFixed == 'true' && Sepoa.request.screen){
        callFunction(Sepoa.request.screen, 'setMenuWidth', [$sObject._vp[0].offsetWidth])
    }


        	menuObj.onGroupClick=function(obj){
        		$(".sepoa_menu_screen").slideUp();
				$(".sepoa_menu_group_li").removeClass("group_active")
				if(!$(obj).next().is(":visible")){
					$(obj).parent().addClass("group_active")
					$(obj).next().slideDown();
				}
        	}

        	SepoaLeftMenu.innerHTML = "";
        	SepoaLeftMenu.classList.add("sepoa_menu");

        	var ul = SepoaLeftMenu.appendChild($('<ul class="sepoa_menu_group" id="sepoa_menu_group"></ul>')[0]);

            for(var i in menuTree){
                var groupData = menuTree[i];
                var childNodes = groupData.childs;

                if(groupData.HIDDEN_FLAG == "Y" || groupData.MENU_FILTERED_YN == "N"){
                    continue;
                }
                if(childNodes.length <= 0){
                    continue;
                }

				var li = ul.appendChild(document.createElement('li'));
        		li.id = "sepoa_menu_group_"+groupData.MENU_ID
        		li.classList.add("sepoa_menu_group_li")

				var menuName = Sepoa.cache.text.get('MENU_' + groupData.MENU_PROFILE_CODE + '.' + groupData.MENU_ID);
				if(menuName.indexOf('Has not found text') == 0) {
					menuName = groupData.MENU_NAME;
				}

        		var h3 = li.appendChild(document.createElement('h3'));
                if(groupData.MENU_IMG && groupData.MENU_IMG.indexOf("xi-") == 0){
                   h3.innerHTML = '<div class="sepoa_menu_group_icon '+groupData.MENU_IMG+'"></div>'+ menuName +'<div class="group_collapse_icon xi-angle-down-thin"></div>';
                }else{
        	       h3.innerHTML = '<div style="'+(groupData.MENU_IMG?('background-image:url(\''+window.CONTEXT_NAME+'/resource/design/imgs/menu/'+groupData.MENU_IMG+'\');'):(''))+'"></div>'+ menuName +'<div class="group_collapse_icon xi-angle-down-thin"></div>';
                }
        		h3.onclick = function(){
	        		menuObj.onGroupClick(this);
    	    	}

        		var subUl = li.appendChild(document.createElement('ul'));
        		subUl.classList.add("sepoa_menu_screen");

                for(var j in childNodes){
                    var node = childNodes[j];

                    if(node.HIDDEN_FLAG == "Y" || node.MENU_FILTERED_YN == "N"){
                        continue;
                    }

                    const item = {
                        id:node.SCREEN_ID,
                        seq:node.ITEM_SEQ,
                        label:Sepoa.cache.text.get("MENU_"+node.MENU_PROFILE_CODE+"."+node.MENU_ID),
                        url:node.URL,
                        mobileUrl:node.MOBILE_URL,
                        img:node.MENU_IMG,
                        summary:node.SUMMARY_FLAG,
                        ext:{
                            mID:node.MENU_ID
                        }
                    }

                    if(item.label.indexOf('Has not found text') == 0) {
                        item.label = node.MENU_NAME;
                    }

                    const li = subUl.appendChild(document.createElement('li'));
                    li.id = "sepoa_menu_screen_"+item.ext.mID;
                    li.classList.add("sepoa_menu_screen_li");
                    li.innerText = item.label;
                    li.addEventListener('click', (e)=>{
                        linkTo(item);
                    })
                }
            }
